**Approach:** extend `write()` to accept the acting user and insert an audit row in the same transaction as the write it's logging:

```js
async function write(text, params, actor) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query(
      "INSERT INTO audit_log (actor_id, table_name, row_id, action, new_row, occurred_at) VALUES ($1,$2,$3,$4,$5, now())",
      [actor?.id, /* table */, res.rows[0]?.id, /* action */, res.rows[0]]
    );
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) { await client.query("ROLLBACK"); throw err; }
  finally { client.release(); }
}
```

